-- State transitions declared for NotificationPreference: an undeclared move is refused.
-- Generated by metaphor-schema

CREATE OR REPLACE FUNCTION sapiens.sapiens_notification_preferences_enabled_transition_check() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NEW."enabled" IS DISTINCT FROM OLD."enabled" AND NOT (
           (COALESCE(OLD."enabled"::text, ''), COALESCE(NEW."enabled"::text, '')) IN (('false', 'true'), ('true', 'false'))
       ) THEN
        RAISE EXCEPTION 'state_transition_not_declared: sapiens_notification_preferences.enabled % -> %', OLD."enabled", NEW."enabled"
            USING ERRCODE = 'check_violation', COLUMN = 'enabled', CONSTRAINT = 'tg_sapiens_notification_preferences__state_transition_not_declared';
    END IF;
    RETURN NEW;
END $$;

DROP TRIGGER IF EXISTS sapiens_notification_preferences_enabled_transition_check ON sapiens.sapiens_notification_preferences;
CREATE TRIGGER sapiens_notification_preferences_enabled_transition_check
    BEFORE UPDATE OF "enabled" ON sapiens.sapiens_notification_preferences
    FOR EACH ROW EXECUTE FUNCTION sapiens.sapiens_notification_preferences_enabled_transition_check();
